<?php
declare(strict_types=1);require_once __DIR__.'/_common.php';require_login();$rows=db()->query('SELECT s.*,t.name tool_name,t.internal_id,e.first_name,e.last_name,u.username FROM inspection_sessions s JOIN tools t ON t.id=s.tool_id LEFT JOIN employees e ON e.id=s.employee_id LEFT JOIN users u ON u.id=s.completed_by ORDER BY s.completed_at DESC LIMIT 500')->fetchAll();$pageTitle='Inspection History';require __DIR__.'/../includes/header.php';?><h1>Inspection History</h1><div class="card"><table class="table"><thead><tr><th>Date</th><th>Type</th><th>Tool</th><th>Employee</th><th>Contents</th><th>Working</th><th>Condition</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['completed_at'])?></td><td><?=e($r['inspection_type'])?></td><td><?=e($r['tool_name'])?> — <?=e($r['internal_id'])?></td><td><?=e(trim(($r['first_name']??'').' '.($r['last_name']??'')))?></td><td><?=$r['contents_complete']===null?'N/A':((int)$r['contents_complete']===1?'Complete':'Missing')?></td><td><?=$r['working_condition']===null?'N/A':((int)$r['working_condition']===1?'Working':'Not working')?></td><td><?=e((string)($r['overall_condition']??''))?></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../includes/footer.php';?>
